function loadConfig(env = process.env) {
  const errors: string[] = []
  const port = Number(env.PORT ?? 3000)
  if (!Number.isInteger(port) || port < 1 || port > 65535) errors.push('PORT must be 1-65535')
  if (!env.DATABASE_URL) errors.push('DATABASE_URL is required')
  if (errors.length) throw new Error(`Invalid config:\n${errors.join('\n')}`)
  return Object.freeze({ port, databaseUrl: env.DATABASE_URL!, debug: env.DEBUG === 'true' })
}
